const groups=[['Today & scenes',[['home','01','Today'],['plan','02','Scene plan'],['restplan','02R','Light only'],['best','12','Personal best'],['feedback','13','Guidance']]],['Check & response',[['wear','03','Headset fit'],['measure','04','EEG measurement'],['self','05','Self-report'],['task','06','Cognitive assessment deferred'],['result','07','Your check'],['features','08','Features & quality'],['light','09','Light session'],['complete','10','Session comparison']]],['History & calibration',[['trends','11','Trends'],['history','11h','Session record'],['calibration','14','Calibration'],['learn','19','Get to know'],['science','18L','Understanding EEG']]],['Interruptions',[['invalid','15','Measurement interruption'],['held','15L','Light interruption'],['safety','16','Safety stop'],['partial','16E','Session ended'],['empty','18','First record']]],['Account & device',[['device','17','Device'],['account','A1','Account'],['profile','A2','Personal details'],['privacy','17P','Data & privacy'],['hearing','A3','Hearing setup'],['splash','00','Splash'],['welcome','00b','Welcome'],['email','00c','Email'],['password','00c1','Password'],['verify','00d','Verify email'],['forgot','00c2','Reset password'],['sent','00c3','Reset link'],['first','00e','First use'],['terms','00T','Terms & privacy']]]];
const params=new URLSearchParams(location.search),embedded=params.get('embed')==='1';
const R={screen:params.get('screen')||'home',scene:params.get('scene')||'fatigue',full:true,lightOnly:false,rest:20,phase:'before',elapsed:0,paused:false,active:false,contact:'good',connected:true,reference:false,conflict:false,rating:3,beforeRating:null,afterRating:null,beforeDone:false,afterDone:false,history:false,resting:false,restElapsed:0,preference:'normal',research:false,cloud:false,saved:[],modal:'',toast:'',cal:'progress',onboard:false,platform:'ios',resume:'',reason:'temperature',age:'',sex:'Prefer not to say',skin:[],hair:'Black',covered:false,email:'',privacyReturn:'device'};
if(R.scene==='cognitive'&&['plan','wear','measure','self','result','light','complete','best'].includes(R.screen)) R.screen='task';
if(R.screen==='best') R.scene='best';
if(R.scene==='brain') R.scene='daily';
