R.full=R.scene!=='daily';
const contextKey='brainlume-v7-daily-context';
let previewUser='preview-local';try{previewUser=localStorage.getItem('brainlume-v7-preview-user')||('preview-'+(globalThis.crypto?.randomUUID?.()||Date.now().toString(36)));localStorage.setItem('brainlume-v7-preview-user',previewUser)}catch{}
function localDay(){const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;}
function readDaily(user=previewUser,day=R.contextDay||localDay()){try{return JSON.parse(localStorage.getItem(contextKey)||'{}')[user]?.[day]||null}catch{return null}}
function writeDaily(value){const day=R.contextDay||localDay();try{let all;try{all=JSON.parse(localStorage.getItem(contextKey)||'{}')}catch{all={}}if(!all||typeof all!=='object'||Array.isArray(all))all={};all[previewUser]??={};all[previewUser][day]={value,updatedAt:new Date().toISOString()};localStorage.setItem(contextKey,JSON.stringify(all));R.dailyDraft=all[previewUser][day];R.contextStorageError=false}catch{R.dailyDraft={value};R.contextStorageError=true}R.editSleep=false;}
function dailyContext(){return R.contextStorageError?R.dailyDraft:readDaily()||R.dailyDraft||null}
function sleepLabel(value){return ({short:'Less than 6 hours',normal:'6–8 hours',long:'More than 8 hours'})[value]||'Not recorded';}
function sleepView(){if(R.lightOnly||R.phase==='after')return '';const d=dailyContext();if(d&&!R.editSleep)return `<section class="sleep-context"><div class="section-head"><h2>Last night’s sleep</h2>${button('Change','sleep-edit','','text-link')}</div><p class="sleep-record">${sleepLabel(d.value)}</p><small>${d.value?'Recorded for today. Used as context, not an EEG conclusion.':'Skipped for today. You can add it later.'}</small>${R.contextStorageError?note('This browser could not save your daily context. It is kept only for this preview.','warning'):''}</section>`;return `<section class="sleep-context"><h2>How long did you sleep last night?</h2><p>Optional, once a day. You can change it later.</p><div class="sleep-options" role="group" aria-label="Last night’s sleep">${[['short','Less than 6 hours'],['normal','6–8 hours'],['long','More than 8 hours']].map(([v,t])=>button(t,'sleep-save',v,'secondary',`aria-pressed="${d?.value===v}"`)).join('')}</div>${button(d?'Keep current entry':'Skip today',d?'sleep-cancel':'sleep-skip','','text-link')}</section>`;}
function withDailyContext(item){if(item.lightOnly)return {...item,sleep:null};const d=item.contextSaved===false||!item.previewUser||!item.contextDay?null:readDaily(item.previewUser,item.contextDay);return {...item,sleep:d?d.value:(item.sleep??null)};}
const bandExamples={A:{eo:[22,24,30,24],ec:[22,24,42,24],quality:82,n:12,chi:[1.42,1.58]},B:{eo:[18,22,38,22],ec:[17,21,56,20],quality:89,n:14,chi:null},C:{eo:[28,30,22,20],ec:[28,29,25,19],quality:76,n:10,chi:null}};
function activeBands(){const index=R.historyIndex??0;return R.bandExample&&bandExamples[R.bandExample]?bandExamples[R.bandExample]:index===2?bandExamples.C:bandExamples.A;}
function usableBands(){return R.contact!=='bad'&&!(R.history&&R.historyIndex===1);}
const bandMeta=[
 ['δ Delta','1–4 Hz',2.2,'#91c6f6','#326895'],
 ['θ Theta','4–8 Hz',6,'#9ea9ff','#5053a9'],
 ['α Alpha','8–12 Hz',10,'#d3adff','#7746a0'],
 ['β Beta','12–20 Hz',16,'#f1b5da','#9b477b']
];

function butterflyPlot(eye){
 const mask=R.hiddenBands||0;
 const traces=bandMeta.map(([name,hz,frequency,dark,light],i)=>{
  if(mask & (1<<i)) return '';
  const phase=i*.7+(eye==='ec'?.85:0);
  const samples=Array.from({length:321},(_,j)=>{
   const t=j/160;
   return (1+.16*Math.sin(2*Math.PI*.6*t+i))*Math.sin(2*Math.PI*frequency*t+phase)+.14*Math.sin(2*Math.PI*(frequency+.7)*t+phase);
  });
  const peak=Math.max(...samples.map(Math.abs));
  const path=samples.map((value,j)=>(j?'L':'M')+(31+j*.8).toFixed(1)+' '+(69-value/peak*43).toFixed(1)).join(' ');
  return `<path class="butterfly-trace" data-band-path="${i}" stroke="${theme()==='dark'?dark:light}" d="${path}"/>`;
 }).join('');
 return `<svg class="butterfly-plot" viewBox="0 0 310 141" role="img" aria-label="Synthetic EEG waveform overlay"><path class="butterfly-grid" d="M31 26H287M31 112H287M31 26V112M95 26V112M159 26V112M223 26V112M287 26V112"/><path class="butterfly-zero" d="M31 69H287"/>${traces}<g class="butterfly-labels"><text x="7" y="29">+1</text><text x="15" y="72">0</text><text x="7" y="115">−1</text>${['0','0.5','1','1.5','2 s'].map((t,i)=>`<text x="${31+i*64}" y="131" text-anchor="middle">${t}</text>`).join('')}</g></svg>`;
}
function bandDistribution(compact=false){
 if(!usableBands()) return `<section class="card band-distribution"><h2>Brainwave data unavailable</h2><p class="caption">Signal quality is insufficient. No waveform or precise distribution is shown.</p></section>`;
 const eye=R.bandEye==='ec'?'ec':'eo', sample=activeBands(), powers=sample[eye];
 const total=powers.reduce((a,b)=>a+b,0), mask=R.hiddenBands||0;
 const sampleName=R.bandExample==='B'?'Demo record B':R.historyIndex===2||R.bandExample==='C'?'Demo record C':'Demo record A';
 return `<section class="card band-distribution"><div class="section-head"><h2>Brainwaves · Butterfly</h2><small>${sampleName}</small></div><div class="segmented" role="group" aria-label="Eye state">${[['eo','Eyes-open data'],['ec','Eyes-closed data']].map(([v,t])=>button(t,'band-eye',v,eye===v?'selected':'',`aria-pressed="${eye===v}"`)).join('')}</div><div class="butterfly-axis">Normalized amplitude</div>${butterflyPlot(eye)}<p class="caption">Relative power · Tap a band to show or hide its trace.</p><div class="butterfly-bands" role="group" aria-label="Show or hide frequency bands">${bandMeta.map(([name,hz,f,dark,light],i)=>{
  const shown=!(mask & (1<<i));
  return button(`<span class="band-key" style="--band-key:${theme()==='dark'?dark:light}"></span><span>${name}<small>${hz}<span class="band-visibility">${shown?'Shown':'Hidden'}</span></small></span><strong>${total>0?(100*powers[i]/total).toFixed(1)+'%':'—'}</strong>`,'butterfly-band',i,'butterfly-band',`aria-pressed="${shown}"`);
 }).join('')}</div>${compact?disclosure('How to read this chart','<p>Synthetic traces share a time axis and zero line. Each trace is normalized separately. Percentages show sample relative power.</p>'):'<p class="caption">Synthetic traces share a time axis and zero line. Each trace is normalized separately. Percentages show sample relative power.</p>'}</section>`;
}

function candidateFeatures(){const sample=activeBands(),eye=R.bandEye==='ec'?'ec':'eo',p=sample[eye],sum=p.reduce((a,b)=>a+b,0);const valid=usableBands(),ratio=(a,b)=>valid&&Number.isFinite(a)&&Number.isFinite(b)&&b>0?(a/b).toFixed(2):'Not calculable',chi=valid&&!R.fitFailed&&sample.chi;const val=chi?`${sample.chi[0].toFixed(2)} / ${sample.chi[1].toFixed(2)}`:'Not calculable';return disclosure('Calculated features · Experimental',`<p>Demo powers only. These are not validated state or ability scores.</p><p>EO = eyes open; EC = eyes closed.</p>${row('ARI · (EC α − EO α) / EO α',ratio(sample.ec[2]-sample.eo[2],sample.eo[2]))}${row('RAP · α / total',valid&&sum>0?(100*p[2]/sum).toFixed(1)+'%':'Not calculable')}${row('TLI · θ / α',ratio(p[1],p[2]))}${row('BAR · β / α',ratio(p[3],p[2]))}${row('χ EO / EC',val)}${row('Δχ · EO − EC',chi?(sample.chi[0]-sample.chi[1]).toFixed(2):'Not calculable')}<p>${!valid?'Quality is insufficient; features cannot be calculated.':R.fitFailed?'The fit failed. χ and Δχ cannot be calculated.':!sample.chi?'No fitted χ was supplied for this example.':'ARI compares absolute alpha powers. RAP, TLI and BAR follow the selected eye state.'}</p><p>Invalid denominators, insufficient quality or failed fitting show “Not calculable”. MMN is unavailable and has zero response weight.</p>`);}
function learnView(){return `<div class="learn-intro"><h1>Get to know<br>everyday brain states.</h1><p class="lead">Understand familiar experiences, without turning them into a ranking.</p></div>${[['Awake','Feeling awake and able to pay attention does not mean you have no fatigue.','sun'],['Fatigued','Mental effort can feel tiring. Fatigue and sleepiness can overlap.','battery'],['Relaxed','Feeling less tense can coexist with being awake.','smile'],['Focused','Attention is directed at a task. Understand focus alongside task performance.','brain']].map(([title,copy,i])=>`<section class="state-learning"><div>${icon(i)}<h2>${title}</h2></div><p>${copy}</p></section>`).join('')}${note('These experiences can coexist. This is not a ranking of your states, and no single EEG band directly reads these feelings.')}<div class="actions">${link('Back to Today','home')}${link('Explore EEG research & limits','science','text-link')}</div>`;}
const slug=()=>sceneData[R.scene],clock=n=>String(Math.floor(n/60)).padStart(2,'0')+':'+String(n%60).padStart(2,'0');
const button=(t,a='view',v='',style='primary',extra='')=>`<button class="${style}" data-a="${a}" data-v="${esc(v)}" ${extra}>${t}</button>`;
const link=(t,to,style='secondary')=>button(t,'view',to,style);
const note=(t,tone='')=>`<div class="notice ${tone}">${icon(tone==='warning'?'info':'info')}<span>${t}</span></div>`;
const row=(a,b)=>`<div class="data-row"><span>${a}</span><strong>${b}</strong></div>`;
const disclosure=(t,b,open=false)=>`<details ${open?'open':''}><summary>${t}${icon('arrow')}</summary><div>${b}</div></details>`;
const orb=(cls='')=>`<div class="photon ${cls}"><canvas width="400" height="400" aria-label="Decorative blue and violet photon sphere"></canvas></div>`;
const footer=(t,v='home')=>`<div class="actions">${link(t,v)}</div>`;
const titleOf=()=>groups.flatMap(x=>x[1]).find(x=>x[0]===R.screen)?.[2]||'Brainlume';
function go(to){if(to!=='measure')window.speechSynthesis?.cancel();if(to==='features')R.featuresReturn=R.screen;R.screen=to;R.modal='';R.toast='';if(!embedded)history.replaceState(null,'',`?screen=${to}&scene=${R.scene}&theme=${R.theme}&lang=${window.BLI18n?.lang||'en'}`);render();}
function record(){return {previewUser,restActualSeconds:R.lightOnly?R.restActualSeconds:null,restEndedEarly:R.lightOnly&&!!R.restEndedEarly,contextDay:R.contextDay||localDay(),contextSaved:!R.contextStorageError,sleep:R.lightOnly?null:dailyContext()?.value??null,scene:R.scene,lightOnly:R.lightOnly,full:R.full,beforeDone:R.beforeDone,afterDone:R.afterDone,beforeRating:R.beforeRating,afterRating:R.afterRating,minutes:R.lightOnly?R.rest:R.full?8+slug().light:4};}
function begin(){R.needsAttention=false;R.restEndedEarly=false;R.restActualSeconds=null;R.dismissed=false;R.restFinished=false;R.resting=false;R.breakReturn=null;R.hiddenBands=0;R.bandEye='eo';R.contextDay=localDay();R.editSleep=false;R.dailyDraft=null;R.beforeDone=R.afterDone=false;R.beforeRating=R.afterRating=null;R.elapsed=0;R.phase='before';R.active=true;R.paused=false;R.contact='good';go('wear');}
function measurementDone(){if(R.contact!=='good'||!R.connected||R.paused)return;R.elapsed=240;R[R.phase==='after'?'afterDone':'beforeDone']=true;if(R.scene==='fatigue')go('self');else finishCheck(null);}
function finishCheck(rating){R[R.phase==='after'?'afterRating':'beforeRating']=rating;if(R.phase==='after'){R.active=false;R.saved.push(record());go('complete');}else{if(!R.full){R.active=false;R.saved.push(record());}go('result');}}
function endLight(early=false){if(R.lightOnly){R.restActualSeconds=early?Math.min(R.elapsed,R.rest*60):R.rest*60;R.restEndedEarly=early;R.active=false;R.paused=false;R.saved.push(record());go('complete');}else{R.phase='after';R.elapsed=0;R.paused=false;go('measure');announcePhase();}}
function phaseMessage(){return [
 'Period 1 of 4. Keep your eyes open and look ahead.',
 'Period 2 of 4. Close your eyes and rest comfortably.',
 'Period 3 of 4. Keep your eyes closed. One minute remains before opening.',
 'Period 4 of 4. Open your eyes and look ahead.'
][Math.min(3,Math.floor(R.elapsed/60))];}
function announcePhase(test=false){
 const message=window.BLI18n?.t(test?'This is a voice preview. Follow the spoken eyes-open and eyes-closed guidance.':phaseMessage())||phaseMessage();
 const live=document.getElementById('phase-announcement');if(live)live.textContent=message;
 if(embedded||document.hidden||(!R.phaseCues&&!test)||!('speechSynthesis' in window)||!('SpeechSynthesisUtterance' in window))return;
 window.speechSynthesis.cancel();const speech=new SpeechSynthesisUtterance(message);speech.lang=window.BLI18n?.lang==='zh'?'zh-CN':'en-US';speech.rate=.95;speech.onerror=e=>{if(!['canceled','interrupted'].includes(e.error))toast('Voice could not play. Use the screen instructions.');};try{window.speechSynthesis.speak(speech)}catch{toast('Voice could not play. Use the screen instructions.');}
}
function guidanceControls(){return `<section class="phase-guidance"><h2>Before you begin</h2><p>Four periods, 60 seconds each: open, closed, closed, open. Stay awake and keep your headset in place.</p><div class="cue-choice">${button(`${icon('sound')}<span>Spoken phase cues</span><strong>${R.phaseCues?'On':'Off'}</strong>`,'phase-cues','','secondary',`aria-pressed="${!!R.phaseCues}"`)}${button('Try voice','cue-test','','text-link','speechSynthesis' in window?'':'disabled')}</div><small>${'speechSynthesis' in window?'Try the voice before starting. Screen instructions remain available.':'Voice is unavailable in this browser. Use the screen instructions.'}</small></section>`;}
function chips(){
 const part=Math.min(3,Math.floor(R.elapsed/60));
 return `<section class="period-progress" aria-label="Four 60-second periods"><div class="period-caption"><strong>EEG collection</strong><span>${part+1} / 4 <span>periods</span></span></div><ol class="period-steps">${['Open','Closed','Closed','Open'].map((title,i)=>`<li class="${i===part?'current':i<part?'finished':''}" ${i===part?'aria-current="step"':''}><span>${i<part?icon('check'):i+1}</span><small>${title}</small></li>`).join('')}</ol></section>`;
}
function eeg(){return `<section class="eeg"><div class="section-head"><h2>EEG signals</h2><small>Simulated signal</small></div>${[1,2,3].map(c=>`<div class="channel ch${c}"><div class="channel-label"><strong>${R.screen==='wear'?['Fp1','Fpz','Fp2'][c-1]:'CH'+c}</strong><span>${!R.connected?'Disconnected':R.contact==='bad'&&c===2?'Adjust contact':'Good contact'} · <b data-value="${c}">—</b> µV</span></div><svg viewBox="0 0 310 70" preserveAspectRatio="none" role="img" aria-label="Channel ${c} simulated EEG"><path class="grid" d="M0 15H310M0 35H310M0 55H310"/><path data-wave="${c}" class="trace" d="M0 35H310"/></svg></div>`).join('')}<div class="axis"><span>−4 s</span><span>−2 s</span><span>Now</span></div></section>`;}

function sessionRoute(){
 if(!R.full||R.lightOnly||!['wear','measure','self','task','result','light'].includes(R.screen))return '';
 const active=R.screen==='light'?1:R.phase==='after'?2:0;
 return `<ol class="ue-session-route" data-stage-overview="true" aria-label="Session stages">${[['Before','4 min'],['Light Session',slug().light+' min'],['After','4 min']].map(([t,time],i)=>`<li class="${i===active?'current':i<active?'finished':''}" ${i===active?'aria-current="step"':''}><span>${i<active?icon('check'):i+1}</span><div><strong>${t}</strong><small>${time}</small></div></li>`).join('')}</ol>`;
}
function main(){switch(R.screen){
case'home':return sceneHome();
case'plan':case'best':return monitoringPlan();
case'restplan':return restLightPlan();
case'wear':return `<h1>A comfortable fit.<br>A clearer signal.</h1><p class="lead">Sit comfortably, relax your forehead and keep hair clear of the contacts.</p>${R.lightOnly?'':`<section class="wear-signals">${eeg()}${button(R.wearWavePaused?'Resume wave preview':'Pause wave preview','wear-waves','','text-link',`aria-pressed="${!!R.wearWavePaused}"`)}<p class="caption">Reduce blinking, jaw clenching and head movement. Contact is confirmed by device quality checks.</p></section>`}${note(!R.connected?'Reconnect your headset to continue.':R.contact==='bad'?'Adjust the center contact and check again.':'Keep a supported position throughout the session.',R.contact==='bad'||!R.connected?'warning':'')}${sleepView()}${disclosure('Headset fit guide',`<img class="product product-lifestyle" src="assets/product-worn-model-20261113.png" alt="Model wearing the Brainlume headset"><div class="fit-list">${['Fp1','Fpz','Fp2'].map((n,i)=>row(n,(!R.connected?'Disconnected':R.contact==='bad'&&i===1?'Adjust contact':'Contact ready')+icon(R.contact==='bad'&&i===1?'info':'check'))).join('')}</div>`)}${R.lightOnly?'':guidanceControls()}`;
case'measure':{const part=Math.min(3,Math.floor(R.elapsed/60));return `${R.full?`<p class="session-stage">${R.phase==='after'?'After check':'Before check'} · ${slug().title}</p>`:''}${chips()}<div class="measurement-heading"><div><h1>${[0,3].includes(part)?'Eyes open':'Eyes closed'}</h1><p>${[0,3].includes(part)?'Rest your gaze ahead.':'Stay comfortable. Let your eyes rest.'}</p></div><div class="period-time"><strong id="period-clock">${clock(R.elapsed%60)}</strong><small>/ 01:00</small></div></div><p class="phase-next">${part===0?'Next: close your eyes.':part===1?'Next: keep your eyes closed.':part===2?'Next: open your eyes.':R.scene==='fatigue'?'Final period. Your check-in comes next.':'Final period. Your EEG record comes next.'}</p>${eeg()}${button(`${icon('sound')} ${R.phaseCues?'Voice cues on':'Voice cues off'}`,'phase-cues','','text-link measurement-voice',`aria-pressed="${!!R.phaseCues}"`)}<p class="signal-caption">${R.paused?'Paused · No new samples are added.':!R.connected?'Disconnected · Recording held.':R.contact==='bad'?'Poor contact · Recording held.':'Illustrative waveforms · Not a live EEG reading.'}</p>${R.paused?note('Resume to continue this period. A contact interruption requires a fresh four-period measurement.'):''}<small class="usable" id="usable">${clock(Math.max(0,R.elapsed-Math.ceil(R.elapsed/60)*4))} usable signal · Period ${part+1} of 4</small>${disclosure('About this measurement','<p>Each period lasts 60 seconds. Open → Closed → Closed → Open. Quality thresholds and transition windows are pending protocol confirmation.</p><p>Passive auditory / MMN output is unavailable pending validation. This prototype plays no tones.</p>')}`;}
case'self':return `<h1>How does this<br>moment feel?</h1><p class="lead">${R.phase==='after'?'After your session':'Before moving on'}, record your own experience.</p><div class="rating-card"><h2>Your fatigue rating</h2><div class="rating-value"><strong id="rating-number">${R.rating}</strong><span>/ 5</span></div><input type="range" min="1" max="5" value="${R.rating}" data-field="rating" aria-label="Fatigue rating"><div class="range-labels"><span>Not tired</span><span>Very tired</span></div><small>Self-reported · Optional</small></div><div class="actions">${button('Save my check-in','rating-save')}${button('Skip for now','rating-skip','','secondary')}</div>`;
case'task':return `<h1>Cognitive assessment deferred</h1><p class="lead">Task testing and cognitive scores are deferred to the next version.</p>${footer('Back to Today')}`;
case'result':return resultView();
case'features':return `<h1>Your brainwaves & quality.</h1><p class="lead">Compare the distribution across eyes-open and eyes-closed periods.</p>${bandDistribution()}<p class="caption">Forehead channels · 1–20 Hz. No Gamma band or scalp topography.</p><section class="card"><h2>Collection quality</h2>${row('Usable data',usableBands()?activeBands().quality+'% · Demo':'Not usable')}${row('Common valid segments',usableBands()?'N = '+activeBands().n+' · Demo':'Not available')}${row('Channels','Fp1 / Fpz / Fp2')}${row('Device bandwidth','1–20 Hz · UE proposal')}<p class="caption">Example quality values are not acceptance thresholds.</p></section>${candidateFeatures()}${disclosure('Collection & calculation notes','<p>Open → Closed → Closed → Open, 60 seconds each. Eye and forehead muscle activity can affect these signals.</p><p>Band boundaries, transition windows, quality gates and primary response direction await validation.</p>')}${disclosure('Versions & comparability',row('Protocol','EO–EC–EC–EO · Draft')+row('Device / firmware','Brainlume · Demo firmware')+row('Algorithm / metrics','Unvalidated · Demo version')+row('Task version','Not supplied')+'<p>Different conditions may exclude a record from comparison.</p>')}${footer('Back to your record',R.featuresReturn||(R.history?'history':'result'))}`;
case'light':{const seconds=(R.lightOnly?R.rest:slug().light)*60;return `<p class="session-stage">${R.lightOnly?'Rest light':slug().goal+' light · Between checks'}</p><h1>Give yourself<br>a little space.</h1><p class="lead">Rest comfortably. Breathe naturally.</p><div class="light-orbit">${orb('large')}<div><strong id="light-clock">${clock(Math.max(0,seconds-R.elapsed))}</strong><span>${R.paused?'Paused':'Time remaining · Demo'}</span></div></div><div class="light-checks">${row('Temperature','Monitoring · Demo')}${row('Cumulative energy','Within demo limit')}${row('Driver current','Normal · Demo')}</div><p class="caption">${R.lightOnly?'No EEG is collected in this light-only session.':'EEG collection during light is pending review; no light-stage EEG is used in this preview.'}</p>${disclosure('About this session','<p>Intensity is not adjusted here. Real light output, wear detection and safety stops require device confirmation. This is a simulated timer, not a device controller.</p>')}`;}
case'complete':return completeView();
case'trends':return trendsView();
case'history':return `<h1>Your session<br>record.</h1><p class="lead">${R.historyIndex===1?`Rest light · ${R.currentRecord?.minutes??20} min`:R.historyIndex===2?'Nov 6 · Excluded from comparison':'Today · '+(sceneData[R.currentRecord?.scene]?.title||slug().title)}</p>${R.historyIndex===2?note('This record uses a different protocol version. It is kept as an individual record and excluded from the trend.','warning'):note('Preview record · This is not a clinical assessment.')}${row('Status',R.historyIndex===2?'Not comparable':'Recorded')}${row('EEG',R.historyIndex===1?'Not collected':'Four 60-second periods')}${R.historyIndex===1?row('Elapsed time',clock(R.currentRecord?.restActualSeconds??1200)):''}${row('Last night’s sleep',sleepLabel(withDailyContext(R.currentRecord||(R.historyIndex===0?R.saved.at(-1):null)||{sleep:null}).sleep))}${row('Sync','Saved in preview memory')}<div class="actions">${R.historyIndex!==1?link('Features & quality','features'):''}${button('Export sample record','export','','secondary')}${button(R.historyReturn&&R.historyReturn!=='trends'?'Back to your record':'Back to Trends','history-return','','text-link')}</div>`;

case'feedback':return feedbackView();
case'calibration':return calibrationView();
case'invalid':return `<div class="state-symbol">${icon('info')}</div><h1>Let’s get a<br>clearer signal.</h1><p class="lead">${!R.connected?'Bluetooth disconnected.':'Contact quality was interrupted.'} This four-period measurement is incomplete.</p>${row('Completed Before check',R.beforeDone?'Saved':'Not available')}${row('Current measurement','No usable result')}${note('Restart the entire current four-period measurement after checking the fit. Missing segments will not be filled in.','warning')}<div class="actions">${button('Check fit & restart','restart')}${link('Review device','device','secondary')}${button('End session','end','','text-link')}</div>`;
case'held':return `<div class="state-symbol">${icon('shield')}</div><h1>Your comparison<br>is on hold.</h1><p class="lead">The light session was interrupted by a disconnect or headset removal.</p>${row('Before check',R.beforeDone?'Saved':'Not collected')}${row('Light stage','Interrupted')}${row('After response','Not generated')}${note('The final handling of light-stage disconnects and removal is pending protocol review. Completed data stays in the record.','warning')}<div class="actions">${link('Review device','device')}${button('Save & return to Today','safe-home','','secondary')}</div>`;
case'safety':return `<div class="state-symbol">${icon('shield')}</div><h1>Stopped to<br>keep you safe.</h1><p class="lead">${({temperature:'Temperature limit',energy:'Cumulative energy limit',current:'Driver current limit',user:'You chose to stop'})[R.reason]} · Simulated event.</p>${note('Light and sound are off in this preview. Real hardware must independently confirm the stop.','warning')}${R.lightOnly?row('Elapsed time',clock(R.restActualSeconds??0)):row('Before check',R.beforeDone?'Saved':'Not available')+row('Session comparison','Unavailable')}<div class="actions">${button('Save & return to Today','safe-home')}${link('Review device','device','secondary')}</div>`;
case'partial':return `<div class="state-symbol">${icon('check')}</div><h1>This session<br>has ended.</h1><p class="lead">Your completed stages are saved. An incomplete session has no before-and-after conclusion.</p>${row('Before check',R.beforeDone?'Saved':'Not completed')}${row('After check',R.afterDone?'Saved':'Not completed')}${footer('Back to Today')}`;
case'empty':return `<h1>Your first record<br>starts here.</h1>${emptyCard()}${footer('Choose a check','home')}`;
case'learn':return learnView();
case'science':return scienceView();
case'device':return `<h1>Ready when<br>you are.</h1><img class="product product-lifestyle" src="assets/product-worn-model-20261113.png" alt="Model wearing the Brainlume headset"><section class="card">${row('Brainlume headset',R.connected?'Connected · Demo':'Offline')}${row('Battery',R.connected?'86% · Demo':'Unavailable')}${row('Signal contacts',R.contact==='bad'?'Needs adjustment':'Check before each measurement')}${row('Light safety','Device confirmation required')}</section><div class="section-head"><h2>Your space</h2></div>${[['profile','Personal details','Sensor conditions and fit'],['calibration','Light calibration','Progress and review outcomes'],['hearing','Hearing setup','Protocol review pending'],['account','Account','Preview account'],['privacy','Data & privacy','Your controls']].map(([id,t,d])=>link(`<span><strong>${t}</strong><small>${d}</small></span>${icon('arrow')}`,id,'list-button')).join('')}${button(R.connected?'Disconnect demo device':'Reconnect demo device','device-toggle','','secondary')}`;
case'account':return `<h1>Your personal<br>space.</h1><div class="avatar">A</div>${row('Email','alex@example.com')}${row('Account','Preview only')}<div class="actions">${link('Personal details','profile')}${link('Data & privacy','privacy','secondary')}${link('Reset password','forgot','secondary')}${link('Sign out of preview','welcome','text-link')}</div>`;
case'profile':return profileView();
case'privacy':return `<h1>Your data.<br>Your choice.</h1><p class="lead">Daily use and research participation are separate choices.</p>${toggle('research','Research participation','Optional, separate consent. Declining does not affect daily use.')}${toggle('cloud','Cloud sync preference','A preview preference only. No files are uploaded.')}<section class="card"><h2>Save before syncing</h2><p>A completed session should be saved locally before a user chooses to sync. Session records stay in preview memory. Optional daily sleep context stays in this browser only.</p></section>${button('Sync preview record','sync','','secondary')}${button('Export sample record','export','','secondary')}${button('Delete preview records','delete','','secondary')}${button('Withdraw research preference','withdraw','','text-link')}${link('Privacy information','terms','list-button')}${R.onboard?button('Continue to device setup','activate-next'):footer('Back to Device','device')}`;
case'hearing':return `<h1>Sound, kept<br>in perspective.</h1><div class="sound-bars" aria-hidden="true">${Array.from({length:15},(_,i)=>`<i style="height:${14+45*Math.sin(i/14*Math.PI)}px"></i>`).join('')}</div><p class="lead">A passive auditory protocol may use tones alongside EEG. You don’t need to count or react to those tones.</p>${note('Hearing thresholds, sound limits and forehead MMN suitability are awaiting validation. No sound or MMN score is generated in V7.')}<div class="actions">${R.onboard?link('Continue to data preferences','privacy'):link('Back to Device','device')}</div>`;
case'splash':return `<div class="splash">${orb('large')}<img src="assets/Brainlume-logo-white.png" alt="Brainlume"><p>A moment for your mind.</p>${link('Begin','welcome')}</div>`;
case'welcome':return `<section class="welcome-content"><h1><span>Understand.</span> <span>Pause.</span><br>Begin again.</h1><p class="lead">A quiet space to check in, explore your patterns and take a guided pause.</p><div class="actions">${link('Get started','email','primary')}${link('Explore the preview','home','secondary')}</div></section>`;
case'email':return `<h1>A space<br>of your own.</h1><p class="lead">Create or access your Brainlume account.</p><form data-form="email"><label>Email<input type="email" name="email" autocomplete="off" required placeholder="you@example.com" value="${esc(R.email)}"></label><p class="caption">Use a sample address in this preview. Nothing is sent.</p><button class="primary" type="submit">Continue</button></form>${link('Terms & privacy','terms','text-link')}`;
case'password':return `<h1>Keep your<br>space private.</h1><form data-form="password"><label>Password<input type="password" name="password" minlength="8" required autocomplete="new-password" placeholder="At least 8 characters"></label><p class="caption">Demo only. Your password is not saved or transmitted.</p><button class="primary" type="submit">Continue preview</button></form>${link('Forgot password?','forgot','text-link')}`;
case'verify':return `<div class="state-symbol">${icon('mail')}</div><h1>Check your<br>inbox.</h1><p class="lead">In the real app, you would verify ${esc(R.email||'your email address')}.</p>${note('No email was sent by this preview.')}<div class="actions">${link('Simulate verification','first')}${button('Resend demo link','resend','','secondary')}</div>`;
case'forgot':return `<h1>A fresh<br>start.</h1><p class="lead">Request a password reset link.</p><form data-form="reset"><label>Email<input type="email" name="email" required placeholder="you@example.com"></label><button class="primary" type="submit">Preview reset request</button></form>`;
case'sent':return `<div class="state-symbol">${icon('mail')}</div><h1>Your next step<br>is in your inbox.</h1>${note('Reset request preview complete. No message was sent.')}<div class="actions">${link('Back to sign in','email')}</div>`;
case'first':return `<h1>Start with<br>your own context.</h1><p class="lead">Your first check records this moment. Comparisons appear only when suitable personal reference data exists.</p>${note('No previous records means no rise-or-fall conclusion. Your record can still include self-report, quality and EEG features.')}<div class="actions">${button('Set up my details','setup')}${link('Explore Today','home','secondary')}</div>`;
case'terms':return `<h1>Clear choices.<br>Clear boundaries.</h1><section class="card"><h2>Preview information</h2><p>This prototype does not create an account or process real health data. All device signals and sample records are illustrative.</p><h2>Production policy required</h2><p>The final terms and privacy notice must explain purposes, retention, access, transfers, export, deletion and withdrawal. Legal text has not been supplied.</p></section>${footer('Back',R.onboard?'privacy':'account')}`;
default:return `<h1>Choose your<br>starting point.</h1>${footer('Back to Today')}`;
}}
function feedbackView(){if(R.resting)return `<h1>Space to<br>simply be.</h1><p class="lead">Set your task aside and breathe naturally.</p><div class="rest-clock" id="rest-clock">${clock(Math.max(0,180-R.restElapsed))}</div><p class="caption">About 3 minutes. You can finish at any time.</p><div class="actions">${button('Finish resting','rest-finish')}</div>`;return `<h1>${R.dismissed?'Continue at<br>your own pace.':R.restFinished?'Take the next step<br>at your pace.':'A short pause,<br>if it suits you.'}</h1><p class="lead">${R.dismissed?'This suggestion is dismissed for this session.':R.restFinished?'Your rest is complete. You can return to your day or rest a little longer.':'You can choose to rest now, or keep going.'}</p>${!R.restFinished&&!R.dismissed?`<section class="card"><h2>Take a short rest</h2><p>Put your task aside. No device or light is needed.</p><div class="duration-small">${icon('clock')} About 3 minutes</div></section><p class="caption">A general rest option, not an EEG-based prescription.</p>`:''}<div class="actions">${button(R.restFinished?'Rest a little longer':'Start resting','rest-start')}${R.restFinished||R.dismissed?(R.breakReturn?button('Back to your record','break-return','','secondary'):link('Back to Today','home','secondary')):button('Not now','rest-dismiss','','secondary')}</div>${disclosure('Adjust rest reminders',`<p>${R.preference==='off'?'Reminders are off.':R.preference==='less'?'Fewer reminders selected.':'You stay in control of suggestions.'}</p>${button('Suggest less often','reminders','less','secondary')}${button('Turn reminders off','reminders','off','text-link')}`)}`;}
function calibrationView(){if(['uncertain','insufficient','none'].includes(R.cal))return `<h1>${R.cal==='insufficient'?'Not enough<br>usable data.':R.cal==='none'?'No clear<br>response found.':'No reliable<br>setting yet.'}</h1><p class="lead">This round has ended without a confirmed personal setting.</p>${row('Attempts','10 / 10 · Example')}${row('Personal setting','Not determined')}${note('No automatic dose increase. An invalid session is not a zero response.','warning')}<div class="actions">${link('Review fit','wear')}${link('Back to Trends','trends','secondary')}</div>`;return `<h1>${R.cal==='done'?'Your calibration,<br>ready for review.':'Learn what<br>fits you.'}</h1><p class="lead">A series of sessions, not one reading.</p><div class="duration"><strong>${R.cal==='done'?'6':'4'}<small> / 6</small></strong><p>Initial sessions · Example</p></div><div class="cal-dots">${Array.from({length:6},(_,i)=>`<i class="${i<4?'done':''}">${i<4?icon('check'):i+1}</i>`).join('')}</div>${note(R.cal==='done'?'Completion requires protocol review and separate evaluation. This preview does not compute a personal dose.':'Individual dose and response values stay hidden until the calibration series is complete.')}<section class="card">${row('Initial sequence','6 fixed sessions')}${row('Control','At least one sham condition')}${row('Maximum attempts','10 · Proposal')}${row('Per-condition repeat','At most once')}</section>${disclosure('When the process stops','<p>Six sessions do not automatically establish a reliable setting. Further attempts follow a predefined review within the limit.</p><p>Missing valid conditions lead to insufficient data; an uncertain peak leads to an uncertain result. Stop thresholds and the main response remain pending validation.</p>')}<div class="actions">${link('Back to Trends','trends')}</div>`;}
function emptyCard(){return `<div class="empty-graphic">${icon('chart')}</div><h2>No comparable records yet.</h2><p class="lead">Start with one record. A personal reference needs matching protocols and suitable data.</p>`;}
const demoTrendRatings=[3,4,3,null,4,5,4];
function trendChart(){
 const days=R.range===30?30:7;
 const values=Array(days-7).fill(null).concat(demoTrendRatings);
 let drawing=false;
 const points=values.map((value,index)=>{
  if(value===null){drawing=false;return null;}
  const point={x:30+index*252/(days-1),y:116-(value-1)*24,value};
  point.command=drawing?'L':'M';drawing=true;return point;
 }).filter(Boolean);
 const path=points.map(p=>`${p.command}${p.x.toFixed(1)} ${p.y}`).join(' ');
 const start=days===7?'Nov 13':'Oct 21';
 return `<svg class="trend-chart" viewBox="0 0 310 158" role="img" aria-label="Self-reported fatigue, 1 to 5. Demo. Missing days stay unconnected."><g class="chart-grid"><path d="M30 20H282M30 68H282M30 116H282"/></g><g class="chart-labels"><text x="6" y="24">5</text><text x="6" y="72">3</text><text x="6" y="120">1</text><text x="30" y="149">${start}</text><text x="246" y="149">Nov 19</text></g><path class="chart-line" d="${path}"/>${points.map(p=>`<circle cx="${p.x.toFixed(1)}" cy="${p.y}" r="4"/>`).join('')}</svg>`;
}
function toggle(key,t,d){return `<div class="toggle-row"><div><strong>${t}</strong><p>${d}</p></div><button class="switch ${R[key]?'on':''}" role="switch" aria-checked="${R[key]}" aria-label="${t}" data-a="toggle" data-v="${key}"><i></i></button></div>`;}
function profileView(){return `<h1>A better fit<br>for your signal.</h1><p class="lead">These details describe sensor conditions. They are not used here to identify you.</p><form data-form="profile"><label>Age<input type="number" name="age" min="18" max="110" value="${esc(R.age)}" placeholder="Your age"></label><label>Sex<select data-field="sex">${['Prefer not to say','Female','Male','Other'].map(x=>`<option ${R.sex===x?'selected':''}>${x}</option>`).join('')}</select></label><div class="field"><span>Skin tone</span><div class="swatches">${['#f0d8c2','#d9b398','#b78363','#81543d','#4b322b'].map((x,i)=>`<button type="button" style="--skin:${x}" data-a="skin" data-v="${i}" class="swatch" aria-label="Skin tone ${i+1}" aria-pressed="${R.skin.includes(i)}">${R.skin.includes(i)?icon('check'):''}</button>`).join('')}</div><small>You can select two neighboring tones.</small></div><label>Hair color<select data-field="hair">${['Black','Dark brown','Brown','Blonde','Auburn','Grey','Other / dyed'].map(x=>`<option ${R.hair===x?'selected':''}>${x}</option>`).join('')}</select></label>${toggle('covered','Hair covers my forehead','Keep hair away from contact and light positions.')}${disclosure('Why ask about skin and hair?','<p>They can affect contact and light delivery. Device-specific calibration must be validated.</p>')}<button type="submit" class="primary">${R.onboard?'Save & continue':'Save details'}</button></form>`;}
const appearanceQuery=matchMedia('(prefers-color-scheme: dark)');
R.theme=params.get('theme')||(()=>{try{return localStorage.getItem('brainlume-v7-theme')||'system'}catch{return'system'}})();
if(!['light','dark','system'].includes(R.theme))R.theme='system';
groups[4][1].splice(1,0,['appearance','17A','Appearance']);
const mainWithoutAppearance=main;
main=function(){if(R.screen==='appearance')return `<h1>Make it<br>feel like you.</h1><p class="lead">Choose an appearance, or let Brainlume follow your phone.</p><div class="appearance-previews"><div class="mini-preview light"><i></i><span></span><b></b><b></b><small>Light</small></div><div class="mini-preview dark"><i></i><span></span><b></b><b></b><small>Dark</small></div></div><div class="appearance-options" role="group" aria-label="Appearance">${[['light','Light','Soft lavender and clear dark text'],['dark','Dark','Deep blue-violet and cool white text'],['system','Use device setting','Changes with your phone’s appearance']].map(([v,t,d])=>button(`<span><strong>${t}</strong><small>${d}</small></span><i class="radio ${R.theme===v?'selected':''}">${R.theme===v?icon('check'):''}</i>`,'theme',v,'list-button',`aria-pressed="${R.theme===v}"`)).join('')}</div><p class="caption">Your appearance preference is saved on this browser. It applies across the app.</p><section class="language-settings"><h2>App language</h2><div class="segmented">${button('简体中文','language','zh',window.BLI18n?.lang==='zh'?'selected':'',`aria-pressed="${window.BLI18n?.lang==='zh'}"`)}${button('English','language','en',window.BLI18n?.lang!=='zh'?'selected':'',`aria-pressed="${window.BLI18n?.lang!=='zh'}"`)}</div></section>${footer('Back to Device','device')}`;let html=mainWithoutAppearance();if(R.screen==='device')html=html.replace('<div class="section-head"><h2>Your space</h2></div>',`<div class="section-head"><h2>Your space</h2></div>${link(`<span><strong>Appearance & language</strong><small>${R.theme==='system'?'Use device setting':R.theme==='dark'?'Dark':'Light'}</small></span>${icon('arrow')}`,'appearance','list-button')}`);return html;};
function theme(){return R.theme==='system'?(appearanceQuery.matches?'dark':'light'):R.theme;}
function sessionActive(){return R.active&&['measure','light','wear','task','self','result'].includes(R.screen);}
function reviewControls(){return `<p class="review-copy">下面是设计演示控件，不属于 App。所有信号、设备状态与任务均为模拟。</p><label>主题<select data-review="theme">${[['system','跟随系统'],['light','浅色'],['dark','深色']].map(([v,t])=>`<option value="${v}" ${R.theme===v?'selected':''}>${t}</option>`).join('')}</select></label>${['measure','light'].includes(R.screen)?button(R.screen==='measure'?'下一段（演示）':'完成光照（演示）','demo-next','','review-button')+button('模拟蓝牙断开','fault','bluetooth','review-button')+button(R.screen==='measure'?'模拟 CH2 接触不良':'模拟摘下设备','fault','contact','review-button'):''}${R.screen==='light'?['temperature','energy','current'].map(x=>button(`安全停止：${x}`,'safety',x,'review-button')).join(''):''}${R.screen==='wear'?button('模拟接触不良','fit-bad','','review-button'):''}${R.screen==='result'?button('切换无参考／有参考','ref','','review-button')+button('切换证据冲突','conflict','','review-button')+button('切换状态需留意（演示）','attention','','review-button'):''}${R.screen==='trends'?button('切换空状态','empty','','review-button'):''}${R.screen==='calibration'?`<label>标定结果<select data-review="cal">${[['progress','初测中'],['done','完成待评审'],['uncertain','尚不能确定'],['insufficient','数据不足'],['none','无明显响应']].map(([v,t])=>`<option value="${v}" ${R.cal===v?'selected':''}>${t}</option>`).join('')}</select></label>`:''}`;}
function modalView(){if(!R.modal)return'';let title='End this session?',body='Completed stages stay saved. An incomplete session has no comparison.',actions=button('Keep going','modal-cancel')+button('End safely','end-confirm','','secondary');if(R.lightOnly&&R.screen==='light'&&R.modal==='end'){
 title='End rest light early?';body='The elapsed time will be saved.';
 actions=button('Keep going','modal-cancel')+button('End light & save time','end-confirm','','secondary');
}if(R.modal==='home'){title='Return to Today?';body='Your session will stay paused. Continue it from Today when you are ready.';actions=button('Pause & return','home-confirm')+button('Stay here','modal-cancel','','secondary')}if(R.modal==='delete'){title='Delete preview records?';body='This clears preview sessions and daily sleep context in this browser. It does not affect a real account.';actions=button('Clear preview records','delete-confirm')+button('Cancel','modal-cancel','','secondary')}return `<div class="modal-backdrop"><section class="modal" role="dialog" aria-modal="true" aria-label="${title}"><h2>${title}</h2><p>${body}</p>${actions}</section></div>`;}
function sessionActionBar(){
 if(!['wear','measure','light'].includes(R.screen))return '';
 if(R.screen==='wear'){
  const ready=R.connected&&R.contact!=='bad';
  const label=!R.connected?'Reconnect · Demo':!ready?'I’ve adjusted the fit':R.lightOnly?'Start light session':'Start measurement';
  const action=ready?'record':'fix';
  const status=!R.connected?'Headset disconnected':!ready?'Adjust headset contact':R.lightOnly?'Headset connected':'3 contacts ready';
  return `<footer class="session-action-bar wear-action-bar" aria-label="Session controls"><p class="session-control-status" role="status">${icon(ready?'check':'info')}<span>${status}</span></p><div class="session-control-buttons">${button('End session','end','','secondary')}${button(`${icon('play')}<span>${label}</span>`,action)}</div></footer>`;
 }
 return `<footer class="session-action-bar" aria-label="Session controls"><div class="session-control-buttons">${button(`${icon(R.paused?'play':'pause')}<span>${R.paused?'Resume':'Pause'}</span>`,'pause','','primary')}${button(`${icon('close')}<span>${R.lightOnly?'End early':'End session'}</span>`,'end','','secondary')}</div>${button(`${icon('shield')}<span>Stop if uncomfortable</span>`,'safety','user','session-safety-stop')}</footer>`;
}
function render(preserve=false){const y=document.querySelector('.phone-main')?.scrollTop||0,nav=['home','trends','device'].includes(R.screen);document.documentElement.dataset.theme=theme();document.getElementById('app').innerHTML=`<div class="workspace"><aside class="rail"><a class="rail-brand" href="index.html"><img src="assets/Brainlume-logo-white.png" alt="Brainlume"></a><p class="version">V7 · UE EDITION</p><nav aria-label="Design screens">${groups.map(([g,list])=>`<p class="group-title">${g}</p>${list.map(([id,n,t])=>button(`<small>${n}</small>${t}`,'preview',id,'rail-link '+(R.screen===id?'selected':''))).join('')}`).join('')}</nav><div class="rail-footer"><a href="board.html">设计总览 ↗</a><a href="pages.html">完整页面与状态 ↗</a><a href="https://brdoyhu.github.io/brainlume-ui-v6/board.html">V6 版本参考 ↗</a></div></aside><section class="stage"><div class="stage-toolbar"><span>BRAINLUME / V7 UE / ${theme().toUpperCase()}</span><div>${button('iOS','platform','ios',R.platform==='ios'?'selected':'')}${button('Android','platform','android',R.platform==='android'?'selected':'')}</div></div><article class="phone ${R.platform==='android'?'android':''}" data-screen="${R.screen}" data-theme="${theme()}">${R.screen==='welcome'?'<div class="welcome-waves" data-gradient-waves data-photo-backdrop aria-hidden="true"></div><img class="welcome-portrait" src="assets/welcome-portrait-20261113.png" alt="Model wearing the Brainlume headset">':''}<div class="status"><span>9:41</span><div>${icon('signal')}${icon('wifi')}${icon('battery')}</div></div><header class="app-header">${nav||['measure','light','welcome'].includes(R.screen)?button('<img src="assets/Brainlume-logo-white.png" alt="Brainlume">','logo','','logo','aria-label="Brainlume · Back to Today"'):button(icon('back'),'back','','icon-button','aria-label="Back"')}${nav?button(`<i class="status-dot ${R.connected?'':'offline'}"></i><span class="device-connection-label">${R.connected?'Connected':'Offline'}</span>`,'view','device','device-pill','aria-label="Device status"'):`<span class="header-title">${['plan','best'].includes(R.screen)?slug().title:titleOf()}</span>`}${button(`<span class="${window.BLI18n?.lang==='en'?'lang-current':''}">EN</span><span aria-hidden="true">/</span><span class="${window.BLI18n?.lang==='zh'?'lang-current':''}">中</span>`,'language',window.BLI18n?.lang==='zh'?'en':'zh','mobile-language',`aria-label="${window.BLI18n?.lang==='zh'?'Switch to English':'Switch to Chinese'}"`)}</header><main class="phone-main ${nav?'with-nav':''}" tabindex="-1">${sessionRoute()}${main()}</main>${sessionActionBar()}${nav?`<nav class="app-nav" aria-label="Main navigation">${[['home','home','Today'],['trends','chart','Trends'],['device','device','Device']].map(([id,i,t])=>button(icon(i)+`<span>${t}</span>`,'view',id,R.screen===id?'selected':'',R.screen===id?'aria-current="page"':'')).join('')}</nav>`:''}${modalView()}${R.toast?`<div class="toast" role="status">${esc(R.toast)}</div>`:''}<div class="home-indicator"></div></article><p class="preview-label">390 × 844 · ${R.platform.toUpperCase()} · INTERACTIVE DESIGN PREVIEW</p></section><aside class="inspector"><p class="version">V7 · 场景与双主题</p><h2>Choose a purpose.<br>Keep the context.</h2><p>新版 UE：日常脑状态监测、监测＋光照及休息光照。</p><p>浅色／深色／跟随系统共用同一套页面与交互。正式算法、任务及质量阈值仍待确认。</p><a href="appearance.html">查看主题对照 ↗</a>${reviewControls()}</aside></div>`;if(preserve)document.querySelector('.phone-main').scrollTop=y;if(R.modal)document.querySelector('.modal button')?.focus();window.BLI18n?.apply(document.getElementById('app'));paintWaves(0);window.BLGradientWaves?.sync();}
function toast(t){R.toast=t;render(true);clearTimeout(R.toastTimer);R.toastTimer=setTimeout(()=>{R.toast='';document.querySelector('.toast')?.remove()},3500);}
function selectScene(v){
 if(R.active){document.querySelector('.resume-card button')?.focus();return;}
 if(v==='cognitive'){go('task');return;}
 R.scene=sceneData[v]?v:'daily';
 R.full=R.scene!=='daily';R.lightOnly=false;R.history=false;R.historyIndex=null;
 go(R.scene==='best'?'best':'plan');
}
function handle(a,v){if(['end','logo','fault','safety','language'].includes(a))window.speechSynthesis?.cancel();switch(a){case'awake':R.awakeFeeling=['awake','sleepy','unsure'].includes(v)?v:null;render(true);break;case'sleep-save':if(['short','normal','long'].includes(v)){writeDaily(v);render(true)}break;case'sleep-skip':writeDaily(null);render(true);break;case'sleep-edit':R.editSleep=true;render(true);break;case'sleep-cancel':R.editSleep=false;render(true);break;case'wear-waves':R.wearWavePaused=!R.wearWavePaused;if(R.wearWavePaused)R.wearWaveTime=motionSeconds;render(true);break;case'band-eye':R.bandEye=v==='ec'?'ec':'eo';render(true);break;case'language':{const drafts=[...document.querySelectorAll('.phone-main input[name]')].map(el=>[el.name,el.value]);window.BLI18n?.set(v);render(true);for(const [name,value]of drafts){const el=[...document.querySelectorAll('.phone-main input[name]')].find(x=>x.name===name);if(el)el.value=value;}break;}case'view':if(v==='best'){selectScene(v);break;}if(v==='self'&&R.scene!=='fatigue'){go('result');break;}if(v==='home'&&sessionActive()){R.resume=R.screen;R.modal='home';R.wasPaused=R.paused;R.paused=true;render(true);return;}if(v==='privacy')R.privacyReturn=R.screen;go(v);break;case'preview':R.active=false;R.paused=false;R.modal='';R.contact='good';R.connected=true;R.lightOnly=v==='restplan';R.history=false;R.historyIndex=null;R.elapsed=0;if(v==='best'){R.scene='best';R.full=true;}if(v==='restplan')R.full=false;if(v==='complete'){R.beforeDone=R.afterDone=true;R.beforeRating=R.scene==='fatigue'?3:null;R.afterRating=R.scene==='fatigue'?2:null;}if(v==='result'){R.beforeDone=true;R.beforeRating=R.scene==='fatigue'?3:null;}go(v);break;case'scene':selectScene(v);break;case'mode':R.full=v==='true';render();break;case'quick':selectScene('daily');break;case'rest':if(R.active){document.querySelector('.resume-card button')?.focus();break;}R.lightOnly=true;R.full=false;R.history=false;go('restplan');break;case'rest-duration':if(restDurations.includes(+v)){R.rest=+v;render(true);}break;case'begin':begin();break;case'record':R.elapsed=0;R.paused=false;R.connected=true;R.contact='good';go(R.lightOnly?'light':'measure');if(!R.lightOnly)announcePhase();break;case'phase-cues':R.phaseCues=!R.phaseCues;window.speechSynthesis?.cancel();render(true);break;case'cue-test':announcePhase(true);break;case'pause':R.paused=!R.paused;if(R.paused)window.speechSynthesis?.cancel();render(true);if(!R.paused&&R.screen==='measure')announcePhase();break;case'demo-next':if(R.paused||!R.connected||R.contact==='bad')return;if(R.screen==='measure'){R.elapsed=(Math.floor(R.elapsed/60)+1)*60;if(R.elapsed>=240)measurementDone();else{render(true);announcePhase();}}else if(R.screen==='light')endLight();break;case'rating-save':finishCheck(R.rating);break;case'rating-skip':finishCheck(null);break;case'start-light':R.elapsed=0;R.paused=false;go('light');break;case'fault':R.paused=true;if(v==='bluetooth')R.connected=false;else R.contact='bad';if(R.lightOnly&&R.screen==='light'){endLight(true);break;}go(R.screen==='light'?'held':'invalid');break;case'fix':R.connected=true;R.contact='good';render(true);break;case'fit-bad':R.contact='bad';render(true);break;case'restart':R.elapsed=0;R.paused=false;R.contact='good';R.connected=true;go('wear');break;case'end':R.modal='end';R.wasPaused=R.paused;R.paused=true;render(true);break;case'modal-cancel':R.paused=R.wasPaused??false;R.modal='';render(true);break;case'end-confirm':if(R.lightOnly&&R.screen==='light'){endLight(true);break;}R.active=false;R.modal='';go('partial');break;case'safety':if(R.lightOnly&&R.screen==='light'){R.restActualSeconds=Math.min(R.elapsed,R.rest*60);R.restEndedEarly=true;R.saved.push(record());}R.reason=v;R.paused=true;R.active=false;go('safety');break;case'safe-home':R.active=false;go('home');break;case'logo':if(sessionActive()){R.resume=R.screen;R.wasPaused=R.paused;R.paused=true;R.modal='home';render(true);}else go('home');break;case'home-confirm':R.modal='';R.paused=true;go('home');break;case'resume':R.paused=false;go(R.resume||'wear');if(R.screen==='measure')announcePhase();break;case'current-record':R.currentRecord=record();R.historyReturn=R.screen;R.history=true;R.historyIndex=R.lightOnly?1:0;go('history');break;case'history':R.currentRecord=v==='0'?R.saved.at(-1)||null:null;R.historyReturn='trends';R.history=true;R.historyIndex=R.currentRecord?.lightOnly?1:+v;go('history');break;case'range':R.range=+v;render(true);break;case'empty':R.empty=!R.empty;render(true);break;case'ref':R.reference=!R.reference;render(true);break;case'conflict':R.conflict=!R.conflict;render(true);break;case'rest-start':R.resting=true;R.restElapsed=0;R.restFinished=false;R.dismissed=false;render();break;case'rest-finish':R.resting=false;R.restFinished=true;render();break;case'rest-dismiss':R.dismissed=true;render();break;case'reminders':R.preference=v;toast(v==='off'?'Rest reminders are off in this preview.':'Fewer reminders selected.');break;case'toggle':R[v]=!R[v];render(true);break;case'delete':R.wasPaused=R.paused;R.modal='delete';render();break;case'delete-confirm':R.saved=[];R.dailyDraft=null;try{localStorage.removeItem(contextKey)}catch{}R.modal='';toast('Preview records cleared.');break;case'withdraw':R.research=false;toast('Research preference withdrawn.');break;case'sync':toast('Sync preview only. No data was uploaded.');break;case'export':{const data={demo:true,notice:'Design sample only, not real health data',records:R.saved.length?R.saved.map(withDailyContext):[{scene:'fatigue',beforeRating:3,afterRating:2,example:true}]};const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='brainlume-v7-sample.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Sample record exported.');break;}case'device-toggle':R.connected=!R.connected;render(true);break;case'skin':{const i=+v;if(R.skin.includes(i))R.skin=R.skin.filter(n=>n!==i);else if(R.skin.length===1&&Math.abs(R.skin[0]-i)===1)R.skin.push(i);else R.skin=[i];render(true);break;}case'setup':R.onboard=true;go('profile');break;case'activate-next':R.onboard=false;R.connected=true;go('first');break;case'resend':toast('Preview only. No email was sent.');break;case'theme':R.theme=v;try{localStorage.setItem('brainlume-v7-theme',v)}catch{}if(!embedded){const u=new URL(location.href);u.searchParams.set('theme',v);history.replaceState(null,'',u.pathname+u.search);}render(true);break;case'platform':R.platform=v;render(true);break;case'back':if(R.screen==='history'){handle('history-return');break;}if(R.screen==='feedback'&&R.breakReturn){handle('break-return');break;}go(({appearance:'device',plan:'home',restplan:'home',wear:R.lightOnly?'restplan':R.scene==='best'?'best':'plan',self:'measure',task:'measure',features:R.featuresReturn||(R.history?'history':'result'),result:'home',complete:'home',history:'trends',calibration:'trends',account:'device',profile:R.onboard?'first':'device',privacy:'device',hearing:R.onboard?'profile':'device',email:'welcome',password:'email',verify:'email',forgot:'account',sent:'email',terms:'account'})[R.screen]||'home');break;}}
document.addEventListener('click',e=>{const el=e.target.closest('[data-a]');if(!el)return;e.preventDefault();handle(el.dataset.a,el.dataset.v);});
document.addEventListener('input',e=>{if(e.target.name==='age')R.age=e.target.value;if(e.target.dataset.field==='rating'){R.rating=+e.target.value;document.getElementById('rating-number').textContent=R.rating;}});
document.addEventListener('change',e=>{const field=e.target.dataset.field;if(field)R[field]=e.target.value;const key=e.target.dataset.review;if(key==='theme')handle('theme',e.target.value);if(key==='cal'){R.cal=e.target.value;render();}});
document.addEventListener('submit',e=>{const type=e.target.dataset.form;if(!type)return;e.preventDefault();const f=new FormData(e.target);if(type==='email'){R.email=f.get('email');go('password')}if(type==='password')go('verify');if(type==='reset')go('sent');if(type==='profile'){R.age=f.get('age');if(R.age&&(+R.age<18||+R.age>110)){toast('Enter an age between 18 and 110.');return;}if(!R.skin.length){toast('Choose a skin tone. Two neighboring tones can be selected.');return;}go(R.onboard?'hearing':'device');}});
appearanceQuery.addEventListener('change',()=>{if(R.theme==='system')render(true);});
document.addEventListener('visibilitychange',()=>{if(document.hidden&&['measure','light'].includes(R.screen)){R.paused=true;window.speechSynthesis?.cancel();render(true);}});
document.addEventListener('keydown',e=>{if(!R.modal)return;if(e.key==='Escape'){handle('modal-cancel');return;}if(e.key==='Tab'){const items=[...document.querySelectorAll('.modal button')];if(e.shiftKey&&document.activeElement===items[0]){items.at(-1).focus();e.preventDefault()}else if(!e.shiftKey&&document.activeElement===items.at(-1)){items[0].focus();e.preventDefault()}}});
function tick(){if(embedded||document.hidden||R.modal)return;if(R.screen==='measure'&&!R.paused&&R.contact==='good'&&R.connected){R.elapsed++;if(R.elapsed>=240){measurementDone();return;}if(R.elapsed%60===0){render(true);announcePhase();return;}const el=document.getElementById('period-clock');if(el)el.textContent=clock(R.elapsed%60);const valid=document.getElementById('usable');if(valid)valid.textContent=window.BLI18n?.t(`${clock(Math.max(0,R.elapsed-Math.ceil(R.elapsed/60)*4))} usable signal · Period ${Math.floor(R.elapsed/60)+1} of 4`)||'';}if(R.screen==='light'&&!R.paused&&R.connected){R.elapsed++;const limit=(R.lightOnly?R.rest:slug().light)*60;if(R.elapsed>=limit){endLight();return;}const el=document.getElementById('light-clock');if(el)el.textContent=clock(limit-R.elapsed);}if(R.screen==='feedback'&&R.resting){R.restElapsed++;const el=document.getElementById('rest-clock');if(el)el.textContent=clock(Math.max(0,180-R.restElapsed));if(R.restElapsed>=180){R.resting=false;R.restFinished=true;render();}}}
setInterval(tick,1000);
let motionSeconds=0,lastPaint=0;const motionPreference=matchMedia('(prefers-reduced-motion: reduce)');
function wave(t,c){return 11*Math.sin((t*8.2+c)*Math.PI*2)+5*Math.sin(t*3.7+c)+3*Math.sin(t*23+c*.6)+2*Math.sin(t*41);}
function paintWaves(t){if(R.screen==='wear'&&R.wearWavePaused)t=R.wearWaveTime||0;for(let c=1;c<=3;c++){const path=document.querySelector(`[data-wave="${c}"]`);if(!path)continue;let d='';for(let i=0;i<=310;i++){const y=35-wave(t+i/78,c)*(.58+c*.07);d+=(i?'L':'M')+i+' '+y.toFixed(2);}path.setAttribute('d',d);const val=document.querySelector(`[data-value="${c}"]`);if(val)val.textContent=!R.connected||R.contact==='bad'?'—':wave(t,c).toFixed(1);}}
let seed=1437;function rnd(){seed=(seed*16807)%2147483647;return(seed-1)/2147483646;}
const photons=Array.from({length:1100},()=>{const z=rnd()*2-1,a=rnd()*Math.PI*2,r=138*(.6+.4*rnd()),p=Math.sqrt(1-z*z);return{x:r*p*Math.cos(a),y:r*z,z:r*p*Math.sin(a),size:.6+rnd()*1.2,h:rnd()};});
function paintOrb(t){document.querySelectorAll('.photon canvas').forEach(canvas=>{const ctx=canvas.getContext('2d');if(!ctx)return;ctx.clearRect(0,0,400,400);const a=t*.13,light=theme()==='light';for(const p of photons){const x=p.x*Math.cos(a)+p.z*Math.sin(a),z=-p.x*Math.sin(a)+p.z*Math.cos(a),scale=400/(400-z),px=200+x*scale,py=200+p.y*scale;ctx.fillStyle=p.h<.16?`rgba(218,104,176,${light?.8:.85})`:p.h<.55?`rgba(169,132,255,${light?.75:.85})`:`rgba(${light?'92,133,222':'149,193,255'},.8)`;ctx.beginPath();ctx.arc(px,py,p.size*scale,0,Math.PI*2);ctx.fill();}});}
function animate(ts){if(ts-lastPaint>42&&!document.hidden){lastPaint=ts;if(!motionPreference.matches&&!R.paused)motionSeconds+=.04;paintWaves(motionSeconds);paintOrb(motionSeconds);}requestAnimationFrame(animate);}
function initPreview(){const st=params.get('state');if(params.get('mode')==='only')R.full=false;if(R.screen==='self'&&R.scene!=='fatigue')R.screen='result';if(params.get('mode')==='full'&&R.scene!=='daily')R.full=true;if(params.get('phase')==='after'){R.phase='after';R.beforeDone=true;if(R.scene==='fatigue')R.beforeRating=3;}if(st==='awake')R.awakeFeeling='awake';if(st==='attention')R.needsAttention=true;if(st==='tired')R.beforeRating=4;if(st==='sleep-recorded')R.dailyDraft={value:'normal'};if(st==='eyes-closed')R.bandEye='ec';if(st==='fit-failed')R.fitFailed=true;if(['A','B','C'].includes(params.get('sample')))R.bandExample=params.get('sample');if(st==='paused')R.paused=true;if(st==='closed1')R.elapsed=60;if(st==='closed2')R.elapsed=120;if(st==='open2')R.elapsed=180;if(st==='contact'){R.contact='bad';R.paused=true;}if(st==='offline')R.connected=false;if(st==='conflict')R.conflict=true;if(st==='reference')R.reference=true;if(st==='empty')R.empty=true;if(st==='missing')R.beforeRating=null;if(['rest','rest-early'].includes(st)||R.screen==='restplan'){R.lightOnly=true;R.full=false;R.restEndedEarly=st==='rest-early';R.restActualSeconds=st==='rest-early'?138:R.rest*60;}if(st==='resting')R.resting=true;if(st==='dismissed')R.dismissed=true;if(st==='finished')R.restFinished=true;if(st==='onboarding')R.onboard=true;if(['uncertain','insufficient','none','done'].includes(st))R.cal=st;if(st?.startsWith('safety-'))R.reason=st.slice(7);if(R.screen==='result'){R.beforeDone=true;if(st!=='missing'&&R.scene==='fatigue'&&st!=='tired')R.beforeRating=3;}if(R.screen==='complete'){R.beforeDone=R.afterDone=!R.lightOnly;if(R.scene==='fatigue'&&!R.lightOnly){R.beforeRating=3;R.afterRating=2;}}if(R.screen==='invalid'){R.contact='bad';R.paused=true;}if(R.screen==='held'){R.beforeDone=true;R.connected=false;R.paused=true;}if(R.screen==='history'){R.history=true;R.historyIndex=st==='excluded'?2:st==='rest'?1:0;}if(!groups.flatMap(g=>g[1]).some(x=>x[0]===R.screen))R.screen='home';}

/* Visual-first UI: short labels, large values, progressively disclosed evidence. */
icons.eye='M2 12s4-7 10-7 10 7 10 7-4 7-10 7S2 12 2 12zM15 12a3 3 0 1 1-6 0 3 3 0 0 1 6 0';
icons.thermometer='M9 14V5a3 3 0 0 1 6 0v9a5 5 0 1 1-6 0M12 8v9';
icons.calendar='M4 5h16v16H4zM8 2v6m8-6v6M4 10h16';
function visualMetric(i,title,value,unit='',caption=''){return `<div class="visual-metric">${icon(i)}<span>${title}</span><strong>${value}<small>${unit}</small></strong>${caption?`<small>${caption}</small>`:''}</div>`;}
function sceneHome(){
 const group=(i,title)=>`${icon(i)}<span><strong>${title}</strong></span>`;
 const choice=(i,title,action,value='')=>button(group(i,title)+icon('arrow'),action,value,'visual-scene-tile ue-entry');
 return `<section class="visual-greeting">${orb()}<p class="home-welcome">Hello, welcome back.</p><h1>How awake<br>do you feel?</h1><div class="awake-checkin" role="group" aria-label="How awake you feel">${[['awake','sun','Awake'],['sleepy','moon','A little sleepy'],['unsure','neutral','Not sure']].map(([v,i,t])=>button(`${icon(i)}<span>${t}</span>`,'awake',v,'awake-option',`aria-pressed="${R.awakeFeeling===v}"`)).join('')}</div>${R.awakeFeeling?'<p class="caption" role="status">Thanks for sharing. Choose any scene below.</p>':''}</section>
 ${R.active?`<section class="resume-card">${button(`${icon('play')} Continue session`,'resume')}</section>`:''}
 <section class="ue-entries" aria-label="Main functions">
 ${choice('wave','Daily brain monitoring','quick')}
 <section class="ue-entry-group" aria-label="Monitoring + light">
 <h2>${icon('sun')} Monitoring + light</h2>
 ${choice('battery','Fatigue check','scene','fatigue')}
 ${choice('trophy','Personal best','scene','best')}
 </section>
 ${choice('moon','Rest light','rest')}
 </section>
 ${button(`${icon('book')}<span><strong>Everyday brain states</strong></span>${icon('arrow')}`,'view','learn','learn-entry')}`;
}

function monitoringPlan(){
 const daily=R.scene==='daily', best=R.scene==='best', plan=slug();
 const steps=R.full?[
  ['scan','Before check (4 min)'],['sun',`${plan.goal} light (${plan.light} min)`],['wave','After check (4 min)']
 ]:[['scan','EEG check (4 min)'],...(daily||best?[]:[['smile','Your experience']]),['wave','Brain state assessment']];
 return `<h1>${plan.headline}</h1>
 ${daily?'':`<div class="segmented" role="group" aria-label="Session mode">${[true,false].map(full=>button(full?'Check + light':'Check only','mode',String(full),R.full===full?'selected':'',`aria-pressed="${R.full===full}"`)).join('')}</div>`}
 <section class="ue-plan-total"><div>${icon('clock')}<strong>${R.full?8+plan.light:4}<small> min</small></strong></div>${best&&R.full?'<p>8-minute light is a prototype setting pending confirmation.</p>':daily?'<p>EEG only · No fatigue rating</p>':!best?'<p>Self-report time is additional.</p>':''}</section>
 <ol class="phase-list ue-plan-steps">${steps.map(([i,t])=>`<li><span class="visual-step-icon">${icon(i)}</span><strong>${t}</strong></li>`).join('')}</ol>
 <div class="actions">${button('Check headset fit','begin')}</div>
 ${disclosure('About this session','<p>Four eyes-open and eyes-closed periods, 60 seconds each. This preview uses simulated device data.</p>'+(R.full?'<p>Light follows personal calibration. Changes do not establish a light effect.</p>':'')+(best?'<p>Task assessment is deferred. This session does not assign a personal-best score or record fatigue ratings.</p>':''))}`;
}

function restLightPlan(){
 return `<h1>Rest light</h1><p class="lead">Light only · No EEG</p>${orb()}
 <div class="section-head"><h2>Choose your time</h2></div>
 <div class="segmented rest-durations" role="group" aria-label="Light duration">${restDurations.map(n=>button(n+' min','rest-duration',n,R.rest===n?'selected':'',`aria-pressed="${R.rest===n}"`)).join('')}</div>
 <div class="actions">${button('Check headset fit','begin')}${link('Back to Today','home','text-link')}</div>
 ${disclosure('About this session','<p>You can end early. Removing the headset ends rest light and saves elapsed time. Light intensity follows device calibration and safety limits.</p>')}`;
}

function contextualRest(rating){
 if(R.lightOnly||!usableBands()||R.dismissed||R.restFinished||R.preference==='off')return '';
 const tired=R.scene==='fatigue'&&rating!==null&&rating>=4;
 if(!tired&&(!R.needsAttention||R.preference==='less'))return '';
 return `<section class="card contextual-rest"><h2>${icon('moon')} Take a short rest</h2><p>${tired?'You reported feeling tired.':'This sample record is marked for attention.'} ${'3 minutes · No device needed'}</p>${button('Rest for a moment','context-rest','','secondary')}</section>`;
}

function sharedEegResult(after=false){
 return `<section class="shared-eeg"><h2>Brain state assessment</h2>${after?'<p class="caption">After check · Demo record</p>':''}${bandDistribution()}
 ${usableBands()?`<div class="visual-status-row"><span>${icon('check')} Usable · Example</span><span>${activeBands().quality}% · N = ${activeBands().n}</span></div>`:''}
 ${link(`${icon('wave')} View features & quality ${icon('arrow')}`,'features','list-button')}</section>`;
}

function resultView(){
 const bad=!usableBands(), fatigue=R.scene==='fatigue', rating=R.beforeRating;
 const heading=bad?'Signal incomplete':R.conflict?'Sources differ':fatigue?'Your check, recorded.':'EEG check complete';
 const nextAction=bad?button(`${icon('scan')} Check fit & restart`,'restart'):R.full&&R.beforeDone?button(`${icon('sun')} Continue to ${slug().light}-minute light`,'start-light'):'';
 return `<header class="result-intro"><h1>${heading}</h1><p class="caption">${slug().title} · Demo</p></header>
 ${bad?note('Quality is insufficient. No state estimate is generated.','warning'):R.conflict?note('The sources do not agree clearly. No single conclusion is drawn.','warning'):''}
 <section class="result-overview" aria-label="This check at a glance">
 ${fatigue?`<div class="result-rating"><span>${icon('battery')} Your fatigue rating</span><strong>${rating??'—'}${rating===null?'':'<small>/ 5</small>'}</strong><small>Self-reported</small></div>`:''}
 <div class="result-status-summary"><span>${icon(bad?'info':'check')}${bad?'Not usable':'Usable · Example'}</span><span>${icon('chart')}${R.reference?'Reference available':'No reference yet'}</span></div></section>
 ${bandDistribution(true)}
 ${link(`${icon('wave')} View features & quality ${icon('arrow')}`,'features','list-button')}
 ${contextualRest(rating)}
 <section class="result-next-actions" aria-label="Next actions"><div class="actions">${nextAction}${button(`${icon('calendar')} View session record`,'current-record','','secondary')}${link('Back to Today','home','text-link')}</div></section>`;
}

function completeView(){
 if(R.lightOnly)return `<div class="state-symbol success">${icon('check')}</div><h1>${R.restEndedEarly?'Light ended early':'Rest light complete'}</h1><p class="lead">Light only · No EEG</p>
 <section class="card rest-receipt">${visualMetric('clock','Elapsed time',clock(R.restActualSeconds??R.rest*60))}${row('Planned duration',R.rest+' min')}</section><div class="actions">${link('Back to Today','home','primary')}${button('View session record','current-record','','secondary')}</div>`;
 return `<div class="state-symbol success">${icon('check')}</div><h1>Session complete</h1><p class="lead">${slug().title} · Before and After</p>
 <section class="card"><div class="compare-row heading"><span>Source</span><span>Before</span><span>After</span></div><div class="compare-row"><span>EEG check</span><strong>${R.beforeDone?'Saved':'—'}</strong><strong>${R.afterDone?'Saved':'—'}</strong></div>
 ${R.scene==='fatigue'?`<div class="compare-row"><span>Fatigue rating</span><strong>${R.beforeRating??'—'}${R.beforeRating!==null?' / 5':''}</strong><strong>${R.afterRating??'—'}${R.afterRating!==null?' / 5':''}</strong></div>`:''}</section>
 ${note('Before-and-after changes are observations. They do not establish an effect of light.')}${contextualRest(R.afterRating)}${R.afterDone?sharedEegResult(true):''}
 <div class="actions">${link('Back to Today','home','primary')}${button('View session record','current-record','','secondary')}</div>`;
};

const activityExample=[0,1,0,2,1,0,3,1,0,1,0,2,0,0,3,1,0,0,1,2,1,0,1,0,2,3,0,1];
function trendsView(){
 const activity=R.trendView==='activity';
 const tabs=`<div class="segmented trend-view-tabs" role="group" aria-label="Trends overview">${button(`${icon('chart')} Trends`,'trend-view','trend',!activity?'selected':'',`aria-pressed="${!activity}"`)}${button(`${icon('calendar')} Usage history`,'trend-view','activity',activity?'selected':'',`aria-pressed="${activity}"`)}</div>`;
 if(R.empty)return `<h1>Your trends</h1>${tabs}${emptyCard()}${footer('Choose a check','home')}`;
 const ranges=`<div class="trend-periods" role="group" aria-label="Time range">${button('7 days','range','7',R.range!==30?'selected':'',`aria-pressed="${R.range!==30}"`)}${button('30 days','range','30',R.range===30?'selected':'',`aria-pressed="${R.range===30}"`)}</div>`;
 return `<h1>Your trends</h1>${tabs}${activity?activityHeatmap():`<section class="trend-panel"><div class="section-head"><h2>Fatigue check-ins</h2>${ranges}</div><p class="caption">Self-reported · 1–5</p>${trendChart()}<div class="trend-reading"><strong>Higher = more tired</strong><span>6 valid sample ratings</span></div><p class="caption">Demo · Missing days are not connected.</p></section>`}
 <div class="section-head recent-heading"><h2>Recent records</h2></div>${[
  ['Today, 09:41',R.saved.length?'Your preview session':'Fatigue check · Example','wave'],
  ['Yesterday, 18:20','Light only · 20 min','sun'],
  ['Nov 6, 08:30','Excluded · Different protocol','info']
 ].map(([date,label,i],index)=>button(`${icon(i)}<span><strong>${date}</strong><small>${label}</small></span>${icon('arrow')}`,'history',index,'list-button')).join('')}
 ${link(`${icon('sun')}<span>Your personal calibration</span>${icon('arrow')}`,'calibration','list-button')}${link('Explore personal best','best','text-link')}`;
}

function activityHeatmap(){
 const days=activityExample.concat([0,0]);
 const selected=R.activityDay;
 const labels=['No record','Check','Light only','Check + light'];
 const selectedValue=days[selected];
 const date=Number.isInteger(selected)?`2026-11-${String(selected+1).padStart(2,'0')}`:'';
 return `<section class="activity-panel"><div class="section-head"><h2>Usage history</h2><small>November 2026 · Demo</small></div>
 <div class="activity-totals">${visualMetric('calendar','Active days',days.filter(Boolean).length,'/ 30')}${visualMetric('wave','Check days',days.filter(v=>v===1||v===3).length,'')}</div>
 <div class="activity-weekdays" aria-hidden="true">${['Monday','Tuesday','Wednesday','Thursday','Friday','Saturday','Sunday'].map(day=>`<span>${window.BLI18n?.lang==='zh'?window.BLI18n.t(day):day.slice(0,1)}</span>`).join('')}</div>
 <div class="activity-grid">${Array.from({length:6},()=>'<span class="activity-spacer" aria-hidden="true"></span>').join('')}${days.map((value,index)=>{
  const date=`2026-11-${String(index+1).padStart(2,'0')}`;
  return button(`<span>${index+1}</span>`,'activity-day',index,`activity-cell level-${value} ${selected===index?'selected':''}`,`aria-pressed="${selected===index}" aria-label="${date} · ${window.BLI18n?.t(labels[value])||labels[value]}"`);
 }).join('')}</div>
 <div class="activity-legend">${labels.map((label,index)=>`<span><i class="level-${index}"></i>${label}</span>`).join('')}</div>
 ${date?`<div class="activity-selection" role="status">${icon(selectedValue===2?'sun':'calendar')}<strong>${date}</strong><span>${['No activity recorded','Check recorded','Light only · No EEG','Check + light'][selectedValue]}</span></div>`:'<p class="caption">Tap a day to view activity.</p>'}
 <small class="caption">Activity only, not a brain-state score.</small></section>`;
}


const detailedMain=main;
main=function(){
 let html=detailedMain();
 if(R.screen==='wear'){
  html=html.replace('<h1>A comfortable fit.<br>A clearer signal.</h1>','<h1>Check your fit.</h1>').replace('<p class="lead">Sit comfortably, relax your forehead and keep hair clear of the contacts.</p>',`<div class="fit-cues"><span>${icon('device')} Adjust fit</span><span>${icon('eye')} Relax your face</span></div>`);
  const t=document.createElement('template');t.innerHTML=html;const sleep=t.content.querySelector('.sleep-context');if(sleep){const wrapper=document.createElement('div');wrapper.innerHTML=disclosure('Last night’s sleep',sleep.outerHTML);sleep.replaceWith(wrapper.firstElementChild)}
  t.content.querySelector('.wear-signals .caption')?.remove();
  const guide=t.content.querySelector('.phase-guidance');if(guide){guide.querySelector('p')?.remove();guide.querySelector('small')?.remove();guide.querySelector('h2')?.remove()}
  html=t.innerHTML;
 }
 if(R.screen==='measure'){
  const t=document.createElement('template');t.innerHTML=html;t.content.querySelector('.session-stage')?.remove();t.content.querySelector('.phase-next')?.remove();
  const note=t.content.querySelector('.signal-caption');if(note&&R.connected&&!R.paused&&R.contact!=='bad')note.remove();html=t.innerHTML;
 }
 if(R.screen==='light'){
  const t=document.createElement('template');t.innerHTML=html;t.content.querySelector('.lead')?.remove();t.content.querySelector('h1').textContent='Time to rest.';
  const checks=t.content.querySelector('.light-checks');checks.innerHTML=`<div class="light-safety-chip">${icon('thermometer')}<span>Temperature</span><strong>Monitoring · Demo</strong></div><div class="light-safety-chip">${icon('bolt')}<span>Energy</span><strong>Within demo limit</strong></div><div class="light-safety-chip">${icon('shield')}<span>Driver current</span><strong>Normal · Demo</strong></div>`;
  const caption=t.content.querySelector('.caption');if(caption){const d=document.createElement('div');d.innerHTML=disclosure('Collection details',caption.outerHTML);caption.replaceWith(d.firstElementChild)}html=t.innerHTML;
 }
 if(R.screen==='self'){html=html.replace('<h1>How does this<br>moment feel?</h1>','<h1>How tired do you feel?</h1>');const t=document.createElement('template');t.innerHTML=html;t.content.querySelector('.lead')?.remove();html=t.innerHTML;}
 if(['device','account','appearance'].includes(R.screen)){const t=document.createElement('template');t.innerHTML=html;t.content.querySelector('.lead')?.remove();const map={profile:'neutral',calibration:'sun',hearing:'sound',account:'neutral',privacy:'shield',appearance:'settings',forgot:'lock'};t.content.querySelectorAll('.list-button,.actions>button').forEach(b=>{if(map[b.dataset.v])b.insertAdjacentHTML('afterbegin',icon(map[b.dataset.v]));});html=t.innerHTML;}
 return html;
};
const detailedHandle=handle;
handle=function(a,v){
 if(a==='butterfly-band'){
  const i=Number(v);if(!Number.isInteger(i)||i<0||i>3)return;
  const next=(R.hiddenBands||0)^(1<<i);
  if(next!==15){R.hiddenBands=next;render(true);document.querySelector(`[data-a="butterfly-band"][data-v="${i}"]`)?.focus({preventScroll:true});}
  return;
 }
 if(a==='attention'){R.needsAttention=!R.needsAttention;render(true);return;}
 if(a==='context-rest'){R.breakReturn=R.screen;go('feedback');return;}
 if(a==='break-return'){R.resting=false;go(R.breakReturn||'home');return;}
 if(a==='history-return'){R.history=false;R.historyIndex=null;go(R.historyReturn||'trends');return;}
 if(a==='trend-view'){if(!['trend','activity'].includes(v))return;R.trendView=v;render();document.querySelector(`[data-a="trend-view"][data-v="${v}"]`)?.focus({preventScroll:true});return;}
 if(a==='activity-day'){const day=Number(v);if(Number.isInteger(day)&&day>=0&&day<30){R.activityDay=day;render(true);document.querySelector(`[data-a="activity-day"][data-v="${day}"]`)?.focus({preventScroll:true})}return;}detailedHandle(a,v);};

initPreview();render();requestAnimationFrame(animate);
function scienceView(){const items=[['Relaxed / eyes closed','Alpha is often more prominent with eyes closed.','The strongest alpha patterns are usually at the back of the head; forehead electrodes offer a limited view.'],['Focused / alert','Some EEG rhythms are studied alongside alertness and active tasks.','Forehead muscle activity can overlap these frequencies. A single increase does not establish greater focus.'],['Drowsy','Drowsiness changes the meaning of an eyes-closed period.','Sleep and artifacts need to be identified before interpreting a measurement.'],['Cognitive load','Demand can increase during a difficult task.','Higher demand is not automatically a worse state. Behavior and task context matter.'],['Aperiodic features','The EEG spectrum has a broad background as well as rhythmic peaks.','Its physiological interpretation is under study. This prototype does not turn it into a direct balance or health score.']];return `<h1>A little context.<br>A clearer picture.</h1><p class="lead">Research patterns and device capabilities are different things. Keep both in view.</p>${items.map(([t,a,b],i)=>`<article class="card science-card"><small>0${i+1}</small><h2>${t}</h2><p>${a}</p><div class="science-limit"><strong>What this means here</strong><p>${b}</p></div></article>`).join('')}${note('Educational copy adapted from the UE. It does not interpret your personal readings or provide a diagnosis.')}<div class="actions">${link('Back to Today','home')}</div>`;}
